bool isBalanced(String s, int left, int right) {
  int balance = 0;
  for (int i = left; i <= right; i++) {
    if (s[i] == '(') balance++;
    else if (s[i] == ')') balance--;

    if (balance < 0) return false; // More closing than opening
  }
  return balance == 0;
}

