String changeBase(int x, int base) {
  if (x == 0) return '0';

  final digits = <int>[];
  while (x > 0) {
    digits.add(x % base);
    x ~/= base;
  }

  // Reverse to get the correct order
  for (var i = digits.length - 1; i >= 0; i--) {
    var digit = digits[i];

    if (digit < 10) {
      digits[i] = digit + 48; // ASCII value of '0' is 48
    } else {
      digits[i] = digit + 55; // ASCII value of 'A' is 65
    }
  }

  String result = '';
  for (final d in digits) {
    result += String.fromCharCode(d);
  }

