int fruitDistribution(String s, int n) {
  if (s == null || s.isEmpty || n <= 0) return 0;

  final List<String> fruits = ['apple', 'banana', 'orange'];
  final Map<String, int> counts = {'apple': 0, 'banana': 0, 'orange': 0};

  for (final char in s.toLowerCase()) {
    if (fruits.contains(char)) {
      counts[char] = (counts[char] ?? 0) + 1;
    }
  }

  var totalFruits = counts.values.fold(0, (sum, count) => sum + count);
  final maxPossible = min(totalFruits, n * 3); // Max possible is 3 per person

  var remaining = n - (totalFruits ~/ 3);
  if (remaining < 0) remaining = 0;

  var distribution = [min(counts['apple']!, 3), min(counts['banana']!, 3), min(counts['orange']!, 3)];
  while (remaining > 0 && distribution.any((f) => f >= 3)) {
    for (var i = 0; i < 3; ++i) {
      if (distribution[i] < 3) {
        distribution[i]++;
        remaining--;
        break;
      }
    }
  }

  return distribution.reduce(max).ceil();
}
