int fruitDistribution(String s, int n) {
  if (s == null || s.isEmpty || n < 1) return 0;

  List<int> counts = [0];
  for (var c in s.split('')) {
    if ('a' <= c && c <= 'z') {
      var index = c.codeUnitAt(0) - 'a'.codeUnitAt(0);
      counts.add(index + 1); // Using the count as a unique identifier per character.
    } else {
      continue; // Skip non-alphabet characters or any other case where we don't want to process
    }
  }

  if (counts.length == 1) return 0;

  // Sort and calculate median
  counts.sort();
  var midIndex = counts.length ~/ 2;
  var median = counts[midIndex];

  // Calculate total number of possible combinations that are less than or equal to median
  var leftCount = counts.sublist(0, midIndex).length;
  var rightCount = counts.sublist(midIndex + 1, counts.length).length;
  var sum = leftCount * rightCount;

  // Count how many values exactly match the median value
  var sameMedianValues = 0;
  for (var i = midIndex; i < counts.length && counts[i] == median; i++) {
    sameMedianValues++;
  }

  var result = sum + sameMedianValues;

  // Check if there's more than one occurrence of the median
  if (sameMedianValues > 1) {
    // If multiple occurrences exist, add the combination of those duplicates
    var duplicateCombinations = sameMedianValues * (sameMedianValues - 1) ~/ 2;
    result += duplicateCombinations;
  }

  return result % n;
}
