int smallestChange(List<int> arr) {
  if (arr.isEmpty || arr.length == 1) return 0;

  int total = arr.reduce((a, b) => a + b);
  List<int> prefixSums = [];
  for (int i = 0; i < arr.length - 1; ++i) {
    prefixSums.add(arr[i]);
  }

  // Sort the array
  List<int> sortedArr = [...arr];
  sortedArr.sort();

  int minDifference = int.maxValue;

  for (int i = 0; i <= sortedArr.length; ++i) {
    int leftSum = prefixSums.take(i).reduce((a, b) => a + b);
    int rightSum = total - leftSum;

    int currentDiff = abs(rightSum - leftSum);
    if (currentDiff < minDifference) {
      minDifference = currentDiff;
    }
  }

  return minDifference;
}

