bool moveOneBall(List<int> arr) {
  final n = arr.length;
  if (n < 2) return false;

  // Find the position of the first ball
  int i = 0;
  while (i < n && arr[i] == -1) ++i;
  if (i >= n) return false; // No balls to move

  // Find the next available slot
  int j = i + 1;
  while (j < n && arr[j] != -1) ++j;
  if (j >= n) return false; // Not enough space

  // Move the ball from i to j-1, and mark j as empty
  for (int k = j - 1; k > i; --k) {
    arr[k] = arr[k - 1];
  }
  arr[i] = -1;
  arr[j - 1] = arr[i];

  return true;
}

