int maxFill(List<List<int>> grid, int capacity) {
  if (grid == null || grid.isEmpty || capacity < 1) return 0;

  final rows = grid.length;
  final cols = grid[0].length;

  // Initialize a DP table with dimensions [rows+1][cols+1]
  List<List<int>> dpTable = List.generate(rows + 1, (_) => List.filled(cols + 1, 0));

  for (var i = 1; i <= rows; ++i) {
    for (var j = 1; j <= cols; ++j) {
      // Calculate the number of items in current cell
      var count = grid[i - 1][j - 1];

      // If we can carry all items from this cell
      if (count <= capacity) {
        // Take as many as possible and add to previous best
        dpTable[i][j] = dpTable[i - 1][j - 1] + count;

        // Try not taking any items here and see which is better
        dpTable[i][j] = max(dpTable[i][j], dpTable[i - 1][j]);

        // Try taking some other combination but keep it within capacity
        for (var k = 1; k < count && k <= capacity; ++k) {
          dpTable[i][j] = max(dpTable[i][j], dpTable[i - 1][j - 1] + k);
        }
      } else {
        // Can't take all items so try different combinations
        for (var k = 1; k <= capacity; ++k) {
          dpTable[i][j] = max(dpTable[i][j], 
                             dpTable[i - 1][j - 1] + min(k, count)); // Only add up to what's available
        }
      }
    }
  }

  // The answer will be stored at dpTable[rows][cols]
  return dpTable[rows][cols];
}

