int maxFill(List<List<int>> grid, int capacity) {
  final rows = grid.length;
  if (rows == 0) return 0;

  final cols = grid[0].length;
  if (cols == 0) return 0;

  // Directions for moving in the four directions
  final List<Offset> directions = [
    Offset(1, 0),
    Offset(-1, 0),
    Offset(0, 1),
    Offset(0, -1)
  ];

  // BFS queue to track cells and their current flow
  Queue<(int row, int col, int flow)> queue = Queue();

  // Mark visited with the amount of water it can carry at that point
  Map<String, bool> visited = <String, bool>{};

  // Initialize the queue with all starting points having zero flow
  for (int r = 0; r < rows; ++r) {
    for (int c = 0; c < cols; ++c) {
      queue.add((r, c, 0));
    }
  }

  while (!queue.isEmpty) {
    var node = queue.removeFirst();
    final row = node.row;
    final col = node.col;
    final currentFlow = node.flow;

    // Check if we've reached a cell with higher elevation than our current flow,
    // which means we cannot pass through this path anymore.
    final height = grid[row][col];
    if (height > currentFlow) continue;

    // If the current cell is not already processed or has more potential flow
    final key = "$row,$col";
    if (visited.containsKey(key)) {
      final storedFlow = visited[key]!;
      if (storedFlow >= currentFlow) continue;
    }
    visited[key] = currentFlow;

    // Try pushing water into neighboring cells
    for (var dir in directions) {
      final newRow = row + dir.dx;
      final newCol = col + dir.dy;

      if (newRow >= 0 && newRow < rows && newCol >= 0 && newCol < cols) {
        // Calculate how much water can be pushed from current cell to neighbor
        final nextHeight = grid[newRow][newCol];

        // The maximum possible flow to push is limited by either:
        // 1. How much water we have available (capacity - currentFlow)
        // 2. Or the minimum between what's allowed by the terrain (currentFlow - nextHeight)

        final availableCapacity = capacity - currentFlow;
        final minAvailable = min(availableCapacity, currentFlow - nextHeight);

        // We can only add up to "minAvailable" units here
        final addedFlow = min(minAvailable, availableCapacity);
        final totalFlowToNeighbor = currentFlow + addedFlow;

        queue.add((newRow, newCol, totalFlowToNeighbor));

        // Update the neighbor's entry in visited map if needed
        final neighborKey = "$newRow,$newCol";
        if (visited.containsKey(neighborKey)) {
          if (totalFlowToNeighbor > visited[neighborKey]!) {
            visited[neighborKey] = totalFlowToNeighbor;
          }
        } else {
          visited[neighborKey] = totalFlowToNeighbor;
        }
      }
    }
  }

  // Find the maximum value among all visited entries
  int maxFlow = 0;
  for (final entry in visited.entries) {
    final flow = entry.value;
    if (flow > maxFlow) {
      maxFlow = flow;
    }
  }

  return maxFlow;
}

