int maxFill(List<List<int>> grid, int capacity) {
  final rows = grid.length;
  if (rows == 0 || grid[0].length == 0) return 0;

  final cols = grid[0].length;
  final n = min(rows, cols);

  var result = 0;

  for (var i = 1; i <= n; i++) {
    // Try to find a square of size i x i
    for (var r = 0; r + i < rows; r++) {
      for (var c = 0; c + i < cols; c++) {
        // Check the sum of the submatrix from [r][c] to [r+i-1][c+i-1]
        bool valid = true;
        int total = 0;

        // Calculate the sum using prefix sums
        final prefixSums = List.generate(
          rows,
          (_) => List.filled(cols, 0),
        );

        // Compute prefix sums with O(1) queries
        for (int row = 0; row < rows; row++) {
          for (int col = 0; col < cols; col++) {
            if (row > 0) prefixSums[row][col] += prefixSums[row - 1][col];
            if (col > 0) prefixSums[row][col] += prefixSums[row][col - 1];
            if (row > 0 && col > 0) 
              prefixSums[row][col] -= prefixSums[row - 1][col - 1];

            prefixSums[row][col] += grid[row][col];
          }
        }

        // Query the rectangle's sum in O(1)
        int querySum(int r2, int c2, int r1 = r, int c1 = c) {
          int val = prefixSums[r2][c2];
          if (r1 > 0) val -= prefixSums[r1 - 1][c2];
          if (c1 > 0) val -= prefixSums[r2][c1 - 1];
          if (r1 > 0 && c1 > 0) val += prefixSums[r1 - 1][c1 - 1];
          return val;
        }

        // Get the sum of current potential square
        int sum = querySum(r + i - 1, c + i - 1);

        if (sum >= 0 && sum <= capacity) {
          valid = false;
          break;
        } else if (sum < 0) {
          // Negative values are invalid because we can't have negative fill amount
          valid = false;
          break;
        } else {
          // We need to check all cells in this i x i area
          // So iterate through each cell and see if any is greater than capacity
          for (int dr = 0; dr < i; dr++) {
            for (int dc = 0; dc < i; dc++) {
              int value = grid[r + dr][c + dc];
              if (value > capacity) {
                valid = false;
                break;
              }
            }
            if (!valid) break;
          }

          if (valid) {
            result = max(result, i * i);
          }
        }
      }
    }
  }

  return result;
}

