int maxFill(List<List<int>> grid, int capacity) {
  final rows = grid.length;
  if (rows == 0) return 0;

  final cols = grid[0].length;
  if (cols == 0) return 0;

  // Initialize a 2D array to keep track of the maximum number of units that can be filled in each cell
  var dp = List.generate(rows, (_) => List.filled(cols, 0));

  for (var i = 0; i < rows; i++) {
    for (var j = 0; j < cols; j++) {
      if (i == 0 || j == 0) {
        // First row or first column
        dp[i][j] = min(grid[i][j], capacity);
      } else {
        // Calculate the minimum between current cell and previous row's value + current cell's value
        dp[i][j] = min(
          grid[i][j],
          dp[i - 1][j] + dp[i][j - 1]
        );
      }
    }
  }

  // The answer is the last cell which represents the maximum fillable amount from top-left to bottom-right
  return dp[rows - 1][cols - 1];
}

