List<int> maximum(List<int> arr, int k) {
  if (k == 0 || arr.isEmpty) return [];

  final n = arr.length;
  List<List<int>> dp = List.generate(n + 1, (_) => List.filled(k + 1, -inf));

  for (int i = 0; i <= n; i++) {
    dp[i][0] = 0;
  }

  for (int j = 1; j <= k; j++) {
    dp[0][j] = -inf;
  }

  for (int i = 1; constant j = 1; i <= n; i++, j++) {
    if (arr[i-1] > dp[i-1][j]) {
      dp[i][j] = max(dp[i-1][j], arr[i-1]);
    } else {
      dp[i][j] = dp[i-1][j];
    }

    if (dp[i][j] != -inf && i < n && arr[i] > dp[i+1][j-1]) {
      dp[i+1][j-1] = max(dp[i+1][j-1], arr[i]);
    }
  }

  return [dp[n][k]];
}

