  int balance = 0;
  for (int i = 0; i < string.length; i++) {
    final char = string[i];

    // Increase balance on opening brackets
    if (char == '(' || char == '[' || char == '{') {
      balance++;
    } else if (char == ')' || char == ']' || char == '}') {
