List<String> splitTokens(String input) {
  var result = [];
  var currentToken = '';
  var insideString = false;
  var escapeChar = false;

  for (var ch in input.split('')) {
    if (escapeChar) {
      currentToken += ch;
      escapeChar = false;
    } else if (ch == '\\') {
      escapeChar = true;
    } else if (ch == '"') {
      insideString = !insideString;
      currentToken += '"';
    } else if (!insideString && ch.isWhitespace) {
      if (currentToken.isNotEmpty) {
        result.add(currentToken);
        currentToken = '';
      }
    } else {
      currentToken += ch;
    }
  }

  if (insideString) {
    throw FormatException('Unmatched quote');
  }

  if (currentToken.isNotEmpty) {
    result.add(currentToken);
  }

  return result;
}

