      // Adjust the indentation based on previous line's indent
      int prevIndent = 0;
      if (i > 0) {
        String prevLine = lines[i-1];

        int pStart = 0;
        while (pStart < prevLine.length && prevLine[pStart] == ' ') pStart++;

        if (prevLine.isNotEmpty && !prevLine.endsWith(' ')) {
          prevIndent = pStart;
        }
      } else {
        // First line, no previous line to reference
        prevIndent = 0;
      }

      int newStart = 0;

      // Determine how much we need to adjust from previous line's indent
      if (start <= prevIndent) {
        newStart = max(0, prevIndent + 2);
      } else {
        newStart = start;
      }

      // Apply the adjusted indentation
      line = ' '.repeat(newStart) + line.substring(start, end+1);
    }

    lines[i] = line;
  }

  return lines.join('\n');
}

