  for (final term in xTerms + nTerms) {
    if (term.isEmpty || !RegExp(r'^-?\d+$').hasMatch(term)) {
      return false;
    }
  }

  int gcdValue = 0;

  // Compute GCD of all numerators and denominators
  for (int i = 0; i < max(xTerms.length, nTerms.length); i++) {
    int numX = int.parse(xTerms[i] ?? '1');
    int denomX = 1;
    if (i + 1 < xTerms.length) {
      denomX = int.parse(xTerms[i + 1]);
    } else {
      denomX = 1;
    }

    int numN = int.parse(nTerms[i] ?? '1');
    int denomN = 1;
    if (i + 1 < nTerms.length) {
      denomN = int.parse(nTerms[i + 1]);
    } else {
      denomN = 1;
    }

    int currentGcd = gcd(abs(numX * denomN), abs(numN * denomX));
    gcdValue = gcd(gcdValue, currentGcd);
  }

  // Simplify the fraction by dividing numerator and denominator by GCD
  int simplifiedNum = (numX / gcdValue).abs();
  int simplifiedDenom = (denomX / gcdValue).abs();

  // Format as "simplified numerator/simplified denominator"
  return '${simplifiedNum.toString()}/${simplifiedDenom.toString()}';
}
