// Helper function to calculate name similarity using Levenshtein distance
double _calculateNameSimilarity(String target, String candidate) {
  var lenTarget = target.length;
  var lenCandidate = candidate.length;

  var dp = List.generate(lenCandidate + 1, (_) => List.filled(lenTarget + 1, 0));

  for (int i = 0; i <= lenCandidate; ++i) {
    dp[i][0] = i;
  }

  for (int j = 0; j <= lenTarget; ++j) {
    dp[0][j] = j;
  }

  for (int i = 1; i <= lenCandidate; ++i) {
    for (int j = 1; j <= lenTarget; ++j) {
      if (candidate[i-1] == target[j-1]) {
        dp[i][j] = dp[i-1][j-1];
      } else {
        dp[i][j] = min(
          dp[i-1][j] + 1,
          dp[i][j-1] + 1,
          dp[i-1][j-1] + 1
        );
      }
    }
  }

  var levDistance = dp[lenCandidate][lenTarget];
  var maxLength = max(lenTarget, lenCandidate);
  return (maxLength - levDistance) / maxLength.toDouble();
}

