String solve(String s) {
  final input = s.trim(); // Trim any surrounding whitespace

  // Handle empty or only whitespace case
  if (input.isEmpty || input.replaceAll(' ', '').isEmpty) {
    return '0';
  }

  var hasLeadingZeros = true;
  var negated = false;
  var numDigits = 0;

  // Check for optional minus sign at the beginning
  if (input.startsWith('-')) {
    negated = true;
    input = input.substring(1);

    // Skip over the '-' and check remaining characters
    hasLeadingZeros = true;
  } else if (input.startsWith('+')) {
    input = input.substring(1);
    hasLeadingZeros = true;
  }

  // Process each character of the number part
  for (final ch in input.split('')) {
    if (ch == '.') {
      // Ignore decimal point as we're handling integers
      continue;
    }

    if (!hasLeadingZeros && ch != '0') {
      // Once non-zero digit found, stop skipping leading zeros
      hasLeadingZeros = false;
    }

    if (ch == '0' && hasLeadingZeros) {
      // Skip this zero since it's a leading zero
      continue;
    }

    numDigits++;
  }

  // Calculate value based on number of significant digits
  final value = pow(10.0, numDigits.toDouble()).toInt() * (negated ? -1 : 1);

  // Format the output according to problem requirements
  return '$value';
}
