String solve(String s) {
  final n = s.length;
  if (n == 0) return '';

  int start = 0, end = n - 1;
  while (start < end) {
    // Skip leading and trailing spaces
    while (s[start] == ' ') start++;
    while (s[end] == ' ') end--;

    // If all characters are processed, break
    if (start >= end) break;

    // Swap the characters at positions [start] and [end]
    final charStart = s.codeUnitAt(start);
    final charEnd = s.codeUnitAt(end);
    s = s.substring(0, start) + String.fromCharCode(charEnd) + 
        s.substring(start+1, end) + String.fromCharCode(charStart) +
        s.substring(end+1);

    start++;
    end--;
  }

  return s;
}

